--Q1. What is the total revenue generated by male vs. female customers?
select
gender,
sum(purchase_amount) as revenue
from customer_behaviour
group by 
gender

--Q2. Which customers used a discount but still spent more than the average purchase amount?
select
customer_id,
purchase_amount,
discount_applied
from customer_behaviour
where discount_applied ='Yes'
group by customer_id,purchase_amount,discount_applied
HAVING avg(purchase_amount )>(select avg(purchase_amount) from customer_behaviour)

--Q3. Which are the top 5 products with the highest average review rating?
select     top 5
item_purchased,
avg(review_rating) as "average product rating"
from customer_behaviour
group by item_purchased,review_rating
order by review_rating desc

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
select 
shipping_type,
avg(purchase_amount)as avg_amount
from customer_behaviour
where shipping_type in ('standard','Express')
group by shipping_type

--Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

select 
subscription_status,
count(customer_id) as total_customer,
sum(purchase_amount) as total_revenue,
avg(purchase_amount) as avg_spend
from customer_behaviour
group by subscription_status

--Q6. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.

WITH customer_summary AS (
	select
	    customer_id,
	    case 
			 when sum(previous_purchases) between 1 and 10 then 'New'
			 when sum(previous_purchases) between 11 and 25 then 'returning'
			 when sum(previous_purchases) between 26 and  50 then 'loyal'
			 else 'others'
		End as customer_regularity
	from customer_behaviour
	GROUP BY customer_id

	)
	select 
		    customer_regularity,
			count(customer_id) as "total number of customers"	
	from customer_summary 
	group by customer_regularity;


	--Q7. What are the top 3 most purchased products within each category?
	WITH items_count AS (
	SELECT CATEGORY,
	item_purchased,
	count(customer_id) AS total_orders,
	row_number() over (partition by category order by count(customer_id) desc) as item_rank
	from customer_behaviour
	group by item_purchased,category
	)
	SELECT 
	item_rank,
	category,
	item_purchased,
	total_orders
	from items_count
	WHERE item_rank <= 3

	


	--Q8. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
	select
	count(customer_id) as repeat_buyers,
	subscription_status

	from customer_behaviour
	where previous_purchases > 5
	group by subscription_status
	


	--Q9. What is the revenue contribution of each age group?
	select
	age_group,
	sum(purchase_amount)as total_revenue

	from customer_behaviour
	group by age_group
	order by  total_revenue desc
